# Generated by test-lab — blind adversarial evaluation
"""Regression coverage for deep-review fail-closed runtime handling."""

import ask.ask as ask_module

from ask.run_state import NoopRunState


def test_deep_review_verifier_failure_returns_needs_attention(monkeypatch, tmp_path):
    target_file = tmp_path / "target.md"
    target_file.write_text("review target", encoding="utf-8")

    monkeypatch.setattr(ask_module, "run_sparta_preflight", lambda *args, **kwargs: {"route": "normal_answer"})
    monkeypatch.setattr(
        ask_module,
        "run_memory_recall",
        lambda *args, **kwargs: {"returncode": 0, "stdout": "[]", "stderr": ""},
    )
    monkeypatch.setattr(ask_module, "parse_memory_output", lambda _stdout: [])

    def fake_synthesise(result, *args, **kwargs):
        result["answer"] = "Invalid review artifact"
        result["oracle"] = {
            "model": "gpt-5.5",
            "reasoning_effort": "high",
            "backend": "subagent-runner",
        }
        result["deep_review"] = {
            "verdict": "INSUFFICIENT_EVIDENCE",
            "verifier_status": "FAIL",
            "verifier_failures": ["target_reconstruction: not assessed"],
            "artifact_paths": {"review_md": "review.md", "review_json": "review.json"},
        }

    monkeypatch.setattr(ask_module, "_synthesise", fake_synthesise)

    result = ask_module.ask(
        "deep review this",
        oracle_model="gpt-5.5",
        oracle_reasoning="high",
        oracle_backend="subagent-runner",
        deep_review=True,
        deep_review_target=str(target_file),
        run_state=NoopRunState("deep-review-fail-closed"),
    )

    assert result["needs_attention"]["reason"] == "deep_review_verifier_failed"
    assert result["needs_attention"]["safe_default"] == "do_not_use_review_verdict"
    assert result["needs_attention"]["verifier_failures"] == ["target_reconstruction: not assessed"]
